# --- HELPER FUNCTION FOR ARGS ---
def _args(update: Update) -> str:
    text = update.message.text or ""
    parts = text.split(maxsplit=1)
    return parts[1].strip() if len(parts) > 1 else ""

# --- MASTER RESPONDER CHECKER ---
def is_master_bot(context: ContextTypes.DEFAULT_TYPE) -> bool:
    try:
        return context.bot.token == BOT_TOKENS[0]
    except:
        return False

# --- FLOOD CONTROL DECORATOR ---
def flood_control(func):
    async def wrapper(*args, **kwargs):
        update = None
        context = None
        for arg in args:
            if isinstance(arg, Update):
                update = arg
            elif isinstance(arg, ContextTypes.CallbackContext):
                context = arg
        
        if not update:
            return await func(*args, **kwargs)

        user_id = update.effective_user.id if update.effective_user else 0
        if user_id in (sudo_users | {OWNER_ID}):
            return await func(*args, **kwargs)
        
        current_time = time.time()
        last_time = user_last_command_time.get(user_id, 0)
        
        if current_time - last_time < FLOOD_DELAY:
            try:
                if context and is_master_bot(context):
                    await update.message.reply_text("✨ *𝑃𝑎𝑟𝑑𝑜𝑛 𝑚𝑒, 𝑠𝑤𝑒𝑒𝑡ℎ𝑒𝑎𝑟𝑡!* 𝑃𝑙𝑒𝑎𝑠𝑒 𝑤𝑎𝑖𝑡 𝑎 𝑙𝑖𝑡𝑡𝑙𝑒 𝑏𝑖𝑡 𝑏𝑒𝑓𝑜𝑟𝑒 𝑠𝑒𝑛𝑑𝑖𝑛𝑔 𝑎𝑛𝑜𝑡ℎ𝑒𝑟 𝑐𝑜ｍｍ𝑎𝑛𝑑. 🌸🪞", parse_mode="Markdown")
            except: pass
            return
            
        user_last_command_time[user_id] = current_time
        return await func(*args, **kwargs)
    return wrapper



# --- REPORT ENGINE ---
async def report(update: Update, title: str, details: str, status: str = "𝑺𝑼𝑪𝑪𝑬𝑺𝑺", context: ContextTypes.DEFAULT_TYPE = None):
    if update.effective_user and update.effective_user.id not in (sudo_users | {OWNER_ID}):
        return
    if context and not is_master_bot(context):
        return
        
    timestamp = datetime.now().strftime("%d-%m-%Y | %H:%M:%S")
    report_msg = (
        f"╔════════════════════════════════════╗\n"
        f"║   🎀✨ **{BOT_NAME} - 𝑶𝑷𝑬𝑹𝑨𝑻𝑰𝑶𝑵𝑨𝑳 𝑹𝑬𝑷𝑶𝑹𝑻** ✨🎀   ║\n"
        f"╚════════════════════════════════════╝\n\n"
        f"• *𝑴𝒐𝒅𝒖𝒍𝒆:* `{title}` 🌸\n"
        f"• *𝑺𝒕𝒂𝒕𝒖𝒔:* `{status}` ✨\n"
        f"• *𝑶𝒘𝒏𝒆𝒓:* `{OWNER_NAME}` 👑\n"
        f"• *𝑻𝒊𝒎𝒆:* `{timestamp}` 🕰️\n\n"
        f"💫 *𝑬𝒙𝒆𝒄𝒖𝒕𝒊𝒐𝒏 𝑫𝒆𝒕𝒂𝒊𝒍𝒔:*\n"
        f"─────────────────────────────────────\n"
        f"{details}\n"
        f"─────────────────────────────────────\n"
        f"✨ *𝐸𝑣𝑒𝑟𝑦𝑡ℎ𝑖𝑛𝑔 𝑖𝑠 𝑟𝑢𝑛𝑛𝑖𝑛𝑔 𝑠𝑜 𝑠𝑚𝑜𝑜𝑡ℎ𝑙𝑦 𝑓𝑜𝑟 𝑢𝑠, 𝑑𝑎𝑟𝑙𝑖𝑛𝑔!* 💖"
    )
    try:
        if update.message:
            await update.message.reply_text(report_msg, parse_mode="Markdown")
    except:
        pass

# --- PING STATUS COMMAND (/ptst) ---
@flood_control
async def cmd_ping_status(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if update.effective_user.id not in (sudo_users | {OWNER_ID}): return
    if not is_master_bot(context): return

    start_global = time.time()
    header_msg = (
        f"╔════════════════════════════════════╗\n"
        f"║   🌸🎀 **{BOT_NAME} - 11 𝑩𝑶𝑻𝑺 𝑴𝑨𝑻𝑹𝑰𝑿** 🎀🌸   ║\n"
        f"╚════════════════════════════════════╝\n\n"
        f"🔍 *𝑷𝒊𝒏𝒈𝒊𝒏𝒈 𝒂𝒍𝒍 11 𝒘𝒐𝒓𝒌𝒆𝒓 𝒏𝒐𝒅𝒆𝒔 𝒘𝒊𝒕𝒉 𝒍𝒐𝒗𝒆...* ⚡\n\n"
    )
    progress_msg = await update.message.reply_text(header_msg + "⏳ *Diagnostic scan in progress, cutie...* 🌸", parse_mode="Markdown")

    async def check_single_token(idx, token):
        try:
            t1 = time.time()
            temp_app = ApplicationBuilder().token(token).build()
            await temp_app.initialize()
            binfo = await temp_app.bot.get_me()
            latency = int((time.time() - t1) * 1000)
            await temp_app.shutdown()
            role = "👑 [Master Node]" if idx == 1 else "🛡️ [Worker Node]"
            return f"  [ {idx:02d} ] 🌸 **{binfo.first_name}** (`@{binfo.username}`)\n        • *Role:* `{role}`\n        • *Status:* `Online & Radiant 🟢`\n        • *Latency:* `{latency}ms` ✨\n"
        except Exception:
            masked = token[:6] + "..." + token[-4:] if len(token) > 10 else "Invalid"
            return f"  [ {idx:02d} ] 🥀 **Node Offline** (`{masked}`)\n        • *Status:* `Invalid Token 🔴`\n        • *Latency:* `N/A ⚠️`\n"

    tasks = [check_single_token(i, t) for i, t in enumerate(BOT_TOKENS, 1)]
    results = await asyncio.gather(*tasks)
    total_time = int((time.time() - start_global) * 1000)
    nodes_report = "".join(results)

    final_report = (
        f"╔════════════════════════════════════╗\n"
        f"║   🌸🎀 **{BOT_NAME} - 11 𝑩𝑶𝑻𝑺 𝑴𝑨𝑻𝑹𝑰𝑿** 🎀🌸   ║\n"
        f"╚════════════════════════════════════╝\n\n"
        f"📊 *𝑪𝒐𝒎𝒑𝒓𝒆𝒉𝒆𝒏𝒔𝒊𝒗𝒆 𝑵𝒐𝒅𝒆 𝑨𝒖𝒅𝒊𝒕 𝑹𝒆𝒑𝒐𝒓𝒕:*\n"
        f"─────────────────────────────────────\n"
        f"{nodes_report}"
        f"─────────────────────────────────────\n"
        f"✨ *𝑻𝒐𝒕𝒂𝒍 𝑨𝒖𝒅𝒊𝒕 𝑻𝒊𝒎𝒆:* `{total_time}ms` ⏱️\n"
        f"💖 *𝑃𝑟𝑜𝑢𝑑𝑙𝑦 𝑚𝑎𝑛𝑎𝑔𝑒𝑑 𝑏𝑦 {OWNER_NAME}! 𝐴𝑙𝑙 𝑏𝑎𝑡𝑡𝑎𝑙𝑖𝑜𝑛𝑠 𝑎𝑟𝑒 𝑟𝑒𝑎𝑑𝑦!* 🌸"
    )
    try:
        await progress_msg.edit_text(final_report, parse_mode="Markdown")
    except:
        await update.message.reply_text(final_report, parse_mode="Markdown")

