# --- PURGE COMMAND ---
@flood_control
async def mod_purge(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if update.effective_user.id not in (sudo_users | {OWNER_ID}): return
    if not update.message.reply_to_message: return
    
    chat_id = update.effective_chat.id
    start_id = update.message.reply_to_message.message_id
    curr_id = update.message.message_id
    count = curr_id - start_id
    
    try:
        await update.message.delete()
        for msg_id in range(curr_id - 1, start_id - 1, -1):
            try:
                await context.bot.delete_message(chat_id=chat_id, message_id=msg_id)
                await asyncio.sleep(0.02)
            except: pass
        try: await context.bot.delete_message(chat_id=chat_id, message_id=start_id)
        except: pass
        
        await report(update, "𝑷𝑼𝑹𝑮𝑬 𝑺𝑼𝑪𝑪𝑬𝑺𝑺", f"𝑺𝒖𝒄𝒄𝒆𝒔𝒔𝒇𝒖𝒍𝒍𝒚 𝒄𝒍𝒆𝒂𝒓𝒆𝒅 `{count}` 𝒎𝒆𝒔𝒔𝒂𝒈𝒆𝒔 𝒇𝒐𝒓 𝒚𝒐𝒖, 𝒅𝒂𝒓𝒍𝒊𝒏𝒈! 🧹✨", context=context)
    except: 
        pass

