# --- GROUP MODERATION ---
@flood_control
async def mod_promote(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if update.effective_user.id not in (sudo_users | {OWNER_ID}) or not update.message.reply_to_message: return
    user = update.message.reply_to_message.from_user
    try:
        await update.effective_chat.promote_member(
            user.id, can_manage_chat=True, can_delete_messages=True, can_manage_video_chats=True,
            can_restrict_members=True, can_promote_members=False, can_change_info=True, can_invite_users=True, can_pin_messages=True
        )
        await report(update, "𝑷𝑹𝑶𝑴𝑶𝑻𝑬", f"𝑆𝑢𝑐𝑐𝑒𝑠𝑠𝑓𝑢𝑙𝑙𝑦 𝑝𝑟𝑜𝑚𝑜𝑡𝑒𝑑 `{user.first_name}` 𝑡𝑜 𝐴𝑑𝑚𝑖𝑛, 𝑑𝑎𝑟𝑙𝑖𝑛𝑔! 👑✨", context=context)
    except: pass

