@flood_control
async def mod_chup(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if update.effective_user.id not in (sudo_users | {OWNER_ID}) or not update.message.reply_to_message: return
    cid, target = update.effective_chat.id, update.message.reply_to_message.from_user
    if cid not in trapped_users: trapped_users[cid] = set()
    trapped_users[cid].add(target.id)
    await report(update, "𝑪𝑯𝑼𝑷 𝑻𝑹𝑨𝑷", f"𝑆𝑖𝑙𝑒𝑛𝑡 𝑡𝑟𝑎𝑝 𝑎𝑐𝑡𝑖𝑣𝑒 𝑜𝑛 `{target.first_name}`, 𝑑𝑎𝑟𝑙𝑖𝑛𝑔. 🤫", context=context)

@flood_control
async def mod_bol(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if update.effective_user.id not in (sudo_users | {OWNER_ID}) or not update.message.reply_to_message: return
    cid, target = update.effective_chat.id, update.message.reply_to_message.from_user
    if cid in trapped_users: trapped_users[cid].discard(target.id)
    await report(update, "𝑩𝑶𝑳 𝑹𝑬𝑳𝑬𝑨𝑺𝑬", f"𝑆𝑖𝑙𝑒𝑛𝑡 𝑡𝑟𝑎𝑝 𝑟𝑒𝑙𝑒𝑎𝑠𝑒𝑑 𝑓𝑜𝑟 `{target.first_name}`, ℎ𝑜𝑛𝑒𝑦. 🗣️", context=context)

@flood_control
async def tts_command(update: Update, context: ContextTypes.DEFAULT_TYPE, fx_name: str, emo: str):
    if update.effective_user.id not in (sudo_users | {OWNER_ID}): return
    text = _args(update)
    if not text:
        if is_master_bot(context):
            await update.message.reply_text("💅🏻 *𝑃𝑎𝑟𝑑𝑜𝑛:* 𝐾𝑖𝑛𝑑𝑙𝑦 𝑝𝑟𝑜𝑣𝑖𝑑𝑒 𝑡𝑒𝑥𝑡 𝑓𝑜𝑟 𝑉𝑁 𝑠𝑦𝑛𝑡ℎ𝑒𝑠𝑖𝑠, ℎ𝑜𝑛𝑒𝑦. ✨", parse_mode="Markdown")
        return
    
    status_msg = await update.message.reply_text(f"{emo} *𝐴𝑐𝑜𝑢𝑠𝑡𝑖𝑐 𝑉𝑁 𝑆𝑦𝑛𝑡ℎ𝑒𝑠𝑖𝑧𝑒𝑟* | `{fx_name}`\n\n• *𝑃𝑎𝑦𝑙𝑜𝑎𝑑:* `{text}`\n• *𝑆𝑡𝑎𝑡𝑢𝑠:* `Synthesizing Audio Voice Note... 🎙️`", parse_mode="Markdown")
    
    try:
        # Generate Audio using gTTS
        tts = gTTS(text=text, lang='hi', slow=False)
        audio_path = f"siren_vn_{update.effective_chat.id}.ogg"
        tts.save(audio_path)
        
        # Send actual Voice Note
        with open(audio_path, 'rb') as voice_file:
            await context.bot.send_voice(
                chat_id=update.effective_chat.id,
                voice=voice_file,
                caption=f"{emo} *𝑆𝑦𝑛𝑡ℎ𝑒𝑠𝑖𝑧𝑒𝑑 𝑉𝑁:* `{fx_name}` 🔊",
                parse_mode="Markdown"
            )
        
        # Cleanup file
        if os.path.exists(audio_path):
            os.remove(audio_path)
            
        try: await status_msg.delete()
        except: pass
        
    except Exception as e:
        await status_msg.edit_text(f"⚠️ *𝑉𝑁 𝑆𝑦𝑛𝑡ℎ𝑒𝑠𝑖𝑠 𝐸𝑟𝑟𝑜𝑟:* `{str(e)}`", parse_mode="Markdown")

# --- NON-BLOCKING ASYNC TASKS (SPFS STYLE: 1 NORMAL + FORWARD SPAM) ---
async def start_sp_task(chat_id, target, context):
    while active_tasks.get(chat_id, {}).get("sp", False):
        try:
            tpl = random.choice(SP_TEMPLATES)
            payload = tpl.format(target=target) if "{target}" in tpl else f"{target} {tpl}"
            sent_msg = await context.bot.send_message(chat_id=chat_id, text=payload)
            await asyncio.sleep(0.001)
            for _ in range(12):
                if not active_tasks.get(chat_id, {}).get("sp", False): break
                await context.bot.forward_message(chat_id=chat_id, from_chat_id=chat_id, message_id=sent_msg.message_id)
                await asyncio.sleep(0.001)
        except: await asyncio.sleep(0.1)

