    while active_tasks.get(chat_id, {}).get("hsp", False):
        try:
            msg = f"**{text} {random.choice(HEART_STYLES)}**"
            sent_msg = await context.bot.send_message(chat_id=chat_id, text=msg, parse_mode="Markdown")
            await asyncio.sleep(0.001)
            for _ in range(12):
                if not active_tasks.get(chat_id, {}).get("hsp", False): break
                await context.bot.forward_message(chat_id=chat_id, from_chat_id=chat_id, message_id=sent_msg.message_id)
                await asyncio.sleep(0.001)
        except: await asyncio.sleep(0.1)

