    if target_id in sudo_users:
        return await update.message.reply_text(f"⚠️ *𝑁𝑜𝑡𝑖𝑐𝑒:* `{target_name}` 𝑖𝑠 𝑎𝑙𝑟𝑒𝑎𝑑𝑦 𝑎 𝑟𝑒𝑔𝑖𝑠𝑡𝑒𝑟𝑒𝑑 𝑆𝑢𝑑𝑜 𝑢𝑠𝑒𝑟, ℎ𝑜𝑛𝑒𝑦. 💖", parse_mode="Markdown")

    if target_id:
        sudo_users.add(target_id)
        await update.message.reply_text(f"✅ *𝑆𝑢𝑐𝑐𝑒𝑠𝑠:* [{target_name}](tg://user?id={target_id}) ℎ𝑎𝑠 𝑏𝑒𝑒𝑛 𝑝𝑟𝑜𝑚𝑜𝑡𝑒𝑑 𝑡𝑜 𝑆𝑢𝑑𝑜, 𝑑𝑎𝑟𝑙𝑖𝑛𝑔! 👑✨", parse_mode="Markdown")

