async def run_single_bot(token: str):
    try:
        app = ApplicationBuilder().token(token).build()
        setup_handlers(app)
        await app.initialize()
        await app.start()
        await app.updater.start_polling(drop_pending_updates=True)
        print(f"[+] Node Active: {token[:8]}...")
        while True:
            await asyncio.sleep(3600)
    except Exception as e:
        print(f"[-] Node Failed {token[:8]}... Error: {e}")

async def main():
    if not BOT_TOKENS or BOT_TOKENS[0] == "TOKEN_1_HERE":
        print("[!] Please configure your 11 bot tokens inside BOT_TOKENS list!")
        return
    print(f"[*] Starting {BOT_NAME} with {len(BOT_TOKENS)} tokens simultaneously...")
    await asyncio.gather(*(run_single_bot(token) for token in BOT_TOKENS))

if __name__ == '__main__':
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        print("\n[!] Shutdown sequence initiated.")
